(()=>{'use strict';let plants=[],units=[],state;const key='uhe-ctg-2027-v1',cfg=window.UHE_CONFIG||{},Y=cfg.year||2027;
const initial=()=>({version:2,configurationVersion:'ctg-unitarias-2026-10-30',study:cfg.study||'CTG Brasil · cenário 2027',notes:cfg.notes||'Manutenção das taxas ONS de setembro/2026 em 2027',participation:!!cfg.participation,rows:plants.map(p=>({id:p.id,include:p.kind==='participacao'?!!cfg.participation:(p.includeDefault??true),teif:p.teif,ip:p.ip,edited:false}))});
function save(){try{localStorage.setItem(key,JSON.stringify(state))}catch(e){$('ctgMessage').textContent='Salvamento local indisponível. Exporte o cenário.'}}
function details(){return plants.map(p=>{const r=state.rows.find(r=>r.id===p.id),b=Engine.band(p.unitMw),ref=Engine.refs[b-1];let d=null;try{d=Engine.availability(r.teif,r.ip)}catch(e){}return {...p,...r,band:b,disp:d,refDisp:Engine.availability(ref[1],ref[2]),selected:r.include&&(p.kind==='operada'||state.participation)}})}
function update(){const data=details(),selected=data.filter(r=>r.selected),valid=selected.filter(r=>r.disp!==null),invalid=selected.length-valid.length,power=valid.reduce((s,r)=>s+r.power,0),equiv=valid.reduce((s,r)=>s+r.power*r.disp/100,0);$('ctgCount').textContent=selected.length;$('ctgUgs').textContent=selected.reduce((s,r)=>s+r.n,0);$('ctgDisp').textContent=invalid||!power?'—':fmt(equiv/power*100)+'%';$('ctgMw').textContent=invalid||!power?'—':fmt(equiv)+' MW';$('ctgMessage').textContent=invalid?`${invalid} usina(s) selecionada(s) com taxas inválidas. Corrija os campos para calcular o portfólio.`:`${selected.length} UHEs selecionadas · ${fmt(power)} MW nas UGs elegíveis. Cenário ${Y}, sem homologação.`;
$('ctgBands').innerHTML=labels.map((l,k)=>{let group=selected.filter(r=>r.band===k+1),bad=group.some(r=>r.disp===null),a=bad?null:Engine.aggregate(group);return `<tr><td>${l}</td><td>${group.length}</td><td>${group.reduce((s,r)=>s+r.n,0)}</td><td>${a?fmt(a.teif,6):'—'}</td><td>${a?fmt(a.ip,6):'—'}</td><td>${a?fmt(a.disp,6):'—'}</td></tr>`}).join('');data.forEach(r=>{const tr=$('ctg-'+r.id);if(!tr)return;tr.classList.toggle('invalid',r.selected&&r.disp===null);tr.querySelector('[data-result="d"]').textContent=r.disp===null?'Inválido':fmt(r.disp,6);tr.querySelector('[data-result="delta"]').textContent=r.disp===null?'—':fmt(r.disp-r.refDisp,6);tr.querySelector('[data-result="source"]').textContent=r.edited?'Taxas do cenário':'ONS set/2026'});renderUnits(data);save()}
function renderUnits(data){$('ctgUnits').innerHTML=units.map(u=>{const active=u.eligible&&!!data.find(p=>p.id===u.plantId&&p.selected);return `<tr><td>${esc(u.plant)}</td><td>${u.ug}</td><td>${fmt(u.mw,2)}</td><td>${active?'Incluída':u.eligible?'Fora da seleção':'Fora do cálculo'}</td><td>${esc(u.reason)}</td></tr>`}).join('')}
function render(){$('ctgStudy').value=state.study;$('ctgNotes').value=state.notes;$('ctgParticipation').checked=state.participation;$('ctgRows').innerHTML=details().filter(r=>r.kind==='operada'||state.participation).map(r=>`<tr id="ctg-${r.id}"><td><input aria-label="Incluir ${esc(r.name)} no cenário CTG" type="checkbox" data-id="${r.id}" data-field="include" ${r.include?'checked':''}></td><td><b>${esc(r.name)}</b><small>${r.id} · ${r.kind==='operada'?'OPERAÇÃO CTG':'PARTICIPAÇÃO ACIONÁRIA'}</small></td><td>${r.n}<small>${esc(r.unitIds[0])}–${esc(r.unitIds[r.unitIds.length-1])}</small></td><td>${fmt(r.power)}</td><td>${r.band} · ${esc(r.unitPowerLabel||fmt(r.unitMw,2))} MW/UG</td><td><input aria-label="TEIF ${Y} ${esc(r.name)}" type="number" min="0" max="100" step="0.000001" value="${r.teif}" data-id="${r.id}" data-field="teif"></td><td><input aria-label="IP ${Y} ${esc(r.name)}" type="number" min="0" max="100" step="0.000001" value="${r.ip}" data-id="${r.id}" data-field="ip"></td><td data-result="d"></td><td>${fmt(r.refDisp,6)}</td><td data-result="delta"></td><td class="source"><span data-result="source"></span><br><a href="${esc(r.source)}" target="_blank" rel="noopener">Cadastro CTG ↗</a><br>${esc(r.ceg)}</td></tr>`).join('');update()}
$('ctgRows').oninput=$('ctgRows').onchange=e=>{const el=e.target,id=el.dataset.id,field=el.dataset.field;if(!id||!['include','teif','ip'].includes(field))return;const r=state.rows.find(r=>r.id===id);if(field==='include')r.include=el.checked;else{r[field]=el.value===''?'':Number(el.value);r.edited=true}update()};
$('ctgStudy').oninput=()=>{state.study=$('ctgStudy').value;save()};$('ctgNotes').oninput=()=>{state.notes=$('ctgNotes').value;save()};
$('ctgParticipation').onchange=()=>{state.participation=$('ctgParticipation').checked;state.rows.find(r=>r.id==='SMN').include=state.participation;render()};
$('ctgReset').onclick=()=>{if(!confirm('Substituir o cenário atual pelos valores da configuração carregada? Exporte um backup para conservar alterações.'))return;state=initial();render()};
function exportable(){CTGModel.validateScenario(state,plants);return {...state,ano:Y,data_consulta:'2026-10-30',base:'ONS setembro/2026',status:'Cenário interno; não homologado',metodo_portfolio:'Soma(P*D)/Soma(P); capacidade integral',resultados:details().map(r=>({id:r.id,nome:r.name,ceg:r.ceg,incluida:r.selected,ugs:r.n,unidades:r.unitIds,potencia_unitaria_mw:r.unitMw,potencia_mw:r.power,teif_pct:r.teif,ip_pct:r.ip,d_cenario_pct:r.disp,d_tabela_pct:r.refDisp,fonte:r.edited?'Cenário editado':'Taxas ONS setembro/2026 mantidas'}))}}
$('ctgBackup').onclick=()=>{try{download('CTG_Brasil_cenario_2027.json',JSON.stringify(exportable(),null,2))}catch(e){toast(e.message)}};
$('ctgExport').onclick=()=>{try{const data=exportable().resultados;download('CTG_Brasil_disponibilidade_2027.csv','\uFEFF'+csv([['sigla','usina','ceg','incluida','ugs','unidades','potencia_unitaria_mw','potencia_mw','teif_cenario_pct','ip_cenario_pct','d_cenario_pct','d_tabela_pct','fonte','hipotese'],...data.map(r=>[r.id,r.nome,r.ceg,r.incluida?1:0,r.ugs,r.unidades.join(', '),r.potencia_unitaria_mw,r.potencia_mw,r.teif_pct,r.ip_pct,r.d_cenario_pct,r.d_tabela_pct,r.fonte,state.notes])]),'text/csv;charset=utf-8')}catch(e){toast(e.message)}};
$('ctgUnitsExport').onclick=()=>{const data=details();download('CTG_Brasil_inventario_UGs.csv','\uFEFF'+csv([['empreendimento','ug','potencia_ativa_mw','elegivel_neste_modelo','incluida_na_selecao','criterio'],...units.map(u=>[u.plant,u.ug,u.mw,u.eligible?1:0,u.eligible&&data.some(p=>p.id===u.plantId&&p.selected)?1:0,u.reason])]),'text/csv;charset=utf-8')};
$('ctgImport').onchange=async e=>{try{let f=e.target.files[0];if(!f)return;if(f.size>1024*1024)throw Error('Limite de 1 MB.');const next=CTGModel.validateScenario(JSON.parse(await f.text()),plants);state=next;render();toast('Cenário CTG importado.')}catch(err){$('ctgMessage').textContent='Importação recusada: '+err.message}finally{e.target.value=''}};
(async()=>{try{[plants,units]=await Promise.all(['ctg.json','ctg-units.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw Error('Cadastro CTG indisponível.');return r.json()})));state=initial();try{const saved=localStorage.getItem(key);if(saved)state=CTGModel.validateScenario(JSON.parse(saved),plants)}catch(e){$('ctgMessage').textContent='Cenário salvo inválido: carregada a base inicial.'}render();const op=plants.filter(p=>p.kind==='operada'&&p.includeDefault!==false),all=plants.filter(p=>p.kind==='participacao'||p.includeDefault!==false);$('configDefaultTotals').textContent='Seleção padrão: '+op.reduce((s,p)=>s+p.n,0)+' UGs · '+fmt(op.reduce((s,p)=>s+p.power,0),2)+' MW.';$('configOptionalTotals').textContent='Com as participações: '+all.reduce((s,p)=>s+p.n,0)+' UGs · '+fmt(all.reduce((s,p)=>s+p.power,0),2)+' MW.';document.querySelector('#ctg h2').textContent='Cenário de disponibilidade · '+Y;document.querySelector('button[data-tab=ctg]').textContent=Y+' · CTG Brasil';}catch(e){$('ctgMessage').textContent=e.message}})();})();
